$(document).on("click",".btn-previous ,.btn-next",function(e){e.preventDefault();let t=$(this),a=t.data("page"),i=t.data("url"),s=t.data("size")||6,n=t.hasClass("btn-next")?a+1:a-1,l=t.data("total"),m=t.data("project"),c="";if(n<=l&&n>=1){$(".profile-loader").css("display","flex"),fetch(`${i}?PageSize=${s}&pagenumber=${n}`).then(e=>e.json()).then(t=>e(t));let e=({data:e,pagination:t,success:a})=>{a&&(e.forEach(e=>{c+=`<div class="col-12 col-md-6 col-lg-4">\n                    <figure class="gallery-item">\n                    <img src="${e.mainImage}" alt="@item.Title">\n                    <figcaption>\n                        <h2>${e.title}</h2>\n                        <a href ="${m}/${e.slug}" class="open-project">View more</a>\n                    </figcaption>\n                    </figure>\n                    </div>`}),$(".galleries-items").html(c),t.nextPage&&$(".btn-next").data("page",parseInt(t.pageNumber)),t.previousPage&&$(".btn-previous").data("page",parseInt(t.pageNumber))),$(".profile-loader").css("display","none")}}});var template='<div class="mfp-figure"><div><div class="mfp-counter"></div><div class="mfp-close"></div></div><div class="mfp-img"></div><div class="mfp-bottom-bar"><div class="mfp-title"></div></div></div>';$(document).on("click",".open-project",function(e){e.preventDefault();let t=$(this).attr("href");fetch(t).then(e=>e.json()).then(e=>open_magnific(e))});const open_magnific=e=>{let t=e.data;if(e.success){let e=[];e.push({src:t.mainImage,title:`\n                    <div class="item-info">\n                    <h3><span>${null!=t.title?t.title:""}</span></h3>\n                    <div class="summary">${null!=t.summary?t.summary:""}</div></div>`}),t.items.length>0&&t.items.forEach(t=>{e.push({src:t.mainImage,title:`\n                    <div class="item-info">\n                    <h3><span>${null!=t.title?t.title:""}</span></h3>\n                    <div class="summary">${null!=t.summary?t.summary:""}</div></div>`})}),$.magnificPopup.open({items:e,type:"image",mainClass:"mfp-gallery",closeMarkup:'<button title="%title%" type="button" class="mfp-close btn btn-close">&#215;</button>',image:{markup:template},gallery:{enabled:!0,tCounter:"%curr% / %total%"}},0)}};